import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"handl Frontend: Custom .handl Syntax","description":"","frontmatter":{"title":"handl Frontend: Custom `.handl` Syntax","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"web/project/adrs/0003-ac-frontend-custom-syntax.md","filePath":"vendored/web/project/adrs/0003-ac-frontend-custom-syntax.md"}'),a={name:`web/project/adrs/0003-ac-frontend-custom-syntax.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-frontend-custom-handl-syntax" tabindex="-1">handl Frontend: Custom <code>.handl</code> Syntax <a class="header-anchor" href="#handl-frontend-custom-handl-syntax" aria-label="Permalink to “handl Frontend: Custom .handl Syntax”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Syntax.</strong> // Line comment user =&gt; http.get(&quot;<a href="https://api.example.com/users/1" target="_blank" rel="noreferrer">https://api.example.com/users/1</a>&quot;)</li><li><strong>How the parser distinguishes fields from data.</strong> No <code>fields:</code> section is needed. The syntax form is the discriminator:</li><li><strong>Output mapping.</strong></li><li><strong>Type inference rules.</strong> The frontend omits <code>type:</code> when the type is obvious:</li><li><strong>Implementation plan.</strong> 1. <strong>New crate <code>handl-frontend-handl</code></strong> — implements <code>Frontend</code> trait. 2. <strong>Parser</strong> — hand-written or <code>pest</code>/<code>nom</code> PEG parser. 3. <strong>Codegen</strong> — walks AST, emits <code>serde_json::Value</code> in canonical structure (1:1 mapping, no logic). 4. <strong>Register in <code>frontend_for</code></strong> — add <code>&quot;handl&quot;</code> match arm in <code>handl-frontend/src/lib.rs</code>. 5. <strong>Source map</strong> — implement <code>parse_with_locations</code> for type error reporting (line/column tracking).</li><li><strong>Verbosity comparison.</strong> YAML remains slightly more compact for pure data objects. <code>.handl</code> wins everywhere else, especially for functions and parameterized fields.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>handl documents are currently written in YAML (or JSON, TOML). The <code>Frontend</code> trait (<code>handl-runtime::Frontend</code>) abstracts format parsing — each frontend parses text into <code>NonFunctionValue</code> and the downstream pipeline (field extraction, type checking, typegen, VM) operates on the value, unaware of the source format.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>69% line reduction for typical documents.</li><li>Type inference eliminates redundant <code>type:</code> declarations.</li><li>Brace-based schemas are visually cleaner than nested YAML maps.</li><li>Arrow syntax unifies fields and functions under one mental model.</li><li>Zero downstream changes — same <code>NonFunctionValue</code>, same pipeline.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (mechanism, tables, proofs, trade-offs): <a href="./../design/0003-ac-frontend-custom-syntax.html"><code>design/0003-ac-frontend-custom-syntax.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};